	input  [ADDR_WIDTH_B-1:0] addrb;
	input  wea;
	input  web;
	input  clka;
	input  clkb;




	
    reg [DATA_WIDTH_A-1:0] memory [0:DATA_DEPTH_A-1];
    reg [DATA_WIDTH_A-1:0] qa;
    reg [DATA_WIDTH_B-1:0] qb;
