    end
    always @(posedge clka) begin
        if(wea) memory[addra]<=dia;
        else qa<=memory[addra];
    end
    always @(posedge clkb) begin
        if(web) memory[addrb]<=dib;
        else qb<=memory[addrb];
    end
    assign doa=qa;
    assign dob=qb;
